layout(color) uniform half4 baseColor;

half4 main(float2 fragCoord) {
    return baseColor;
}

uniform float time;
uniform float speed;

half4 main(float2 fragCoord) {
    float t = 0.5 + 0.5 * sin(time * speed);
    half3 a = half3(0.10, 0.40, 0.90);
    half3 b = half3(0.95, 0.35, 0.20);
    return half4(mix(a, b, t), 1.0);
}

uniform float2 resolution;
layout(color) uniform half4 startColor;
layout(color) uniform half4 endColor;
uniform float angle;

half4 main(float2 fragCoord) {
    float2 centered = fragCoord / resolution - 0.5;
    float radians = angle * 0.01745329252;
    float2 direction = float2(cos(radians), sin(radians));
    float span = abs(direction.x) + abs(direction.y);
    float t = dot(centered, direction) / span + 0.5;
    half3 color = mix(startColor.rgb, endColor.rgb, clamp(t, 0.0, 1.0));
    return half4(color, 1.0);
}

uniform float2 resolution;
uniform float radius;

half4 main(float2 fragCoord) {
    float2 uv = fragCoord / resolution - 0.5;
    uv.x *= resolution.x / resolution.y;
    float d = length(uv);
    float t = clamp(d / radius, 0.0, 1.0);
    half3 inner = half3(1.0, 0.85, 0.30);
    half3 outer = half3(0.10, 0.05, 0.25);
    return half4(mix(inner, outer, t), 1.0);
}

uniform float2 resolution;
uniform float time;
uniform float speed;

half4 main(float2 fragCoord) {
    float2 uv = fragCoord / resolution - 0.5;
    uv.x *= resolution.x / resolution.y;
    float r = length(uv);
    float a = atan(uv.y, uv.x);
    float swirl = a + r * 8.0 - time * speed;
    float v = 0.5 + 0.5 * sin(swirl * 4.0);
    half3 col = mix(half3(0.10, 0.05, 0.30), half3(1.0, 0.45, 0.85), v);
    return half4(col, 1.0);
}

uniform float2 resolution;
uniform float time;
uniform float radius;
uniform float softness;

half4 main(float2 fragCoord) {
    float2 uv = fragCoord / resolution - 0.5;
    uv.x *= resolution.x / resolution.y;
    float r = length(uv);
    float pulse = radius + 0.10 * sin(time * 2.0);
    float v = 1.0 - smoothstep(pulse, pulse + softness, r);
    half3 col = mix(half3(0.0), half3(0.95, 0.55, 0.30), v);
    return half4(col, 1.0);
}

uniform float2 resolution;
uniform float count;
uniform float skew;
layout(color) uniform half4 inkA;
layout(color) uniform half4 inkB;
half4 main(float2 fragCoord) {
    float2 uv = fragCoord / resolution;
    float v = step(0.5, fract((uv.x + uv.y * skew) * count));
    return mix(inkA, inkB, half(v));
}

uniform float2 resolution;
uniform float cells;
uniform float radius;
half4 main(float2 fragCoord) {
    float2 uv = fragCoord / resolution;
    uv.x *= resolution.x / resolution.y;
    float2 g = fract(uv * cells) - 0.5;
    float d = length(g) - radius;
    float a = 1.0 - smoothstep(0.0, 0.01, d);
    half3 bg = half3(0.95, 0.92, 0.88);
    half3 dot = half3(0.95, 0.30, 0.55);
    return half4(mix(bg, dot, a), 1.0);
}

uniform float2 resolution;
uniform float scale;
half4 main(float2 fragCoord) {
    float2 uv = (fragCoord - 0.5 * resolution) / resolution.y * scale;
    // Two interleaved rectangular lattices form a hex tiling.
    float2 a = float2(1.0, 1.732);
    float2 r1 = mod(uv, a) - a * 0.5;
    float2 r2 = mod(uv + a * 0.5, a) - a * 0.5;
    float2 c = (dot(r1, r1) < dot(r2, r2)) ? r1 : r2;
    // Distance to hex center, with edge AA.
    float d = length(c);
    float edge = smoothstep(0.42, 0.46, d);
    half3 fill = half3(0.05, 0.07, 0.16);
    half3 line = half3(0.95, 0.75, 0.20);
    return half4(mix(fill, line, half(edge)), 1.0);
}

    uniform float2 resolution;
    uniform float cells;
    uniform float thickness;

float hash21(float2 p) {
    return fract(sin(dot(p, float2(12.9898, 78.233))) * 43758.5453);
}
float valueNoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    float a = hash21(i);
    float b = hash21(i + float2(1.0, 0.0));
    float c = hash21(i + float2(0.0, 1.0));
    float d = hash21(i + float2(1.0, 1.0));
    float2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}
float fbm(float2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 6; i++) {
        v += a * valueNoise(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

    half4 main(float2 fragCoord) {
        float2 uv = fragCoord / resolution * cells;
        float2 i = floor(uv);
        float2 f = fract(uv);
        // Randomly mirror half the tiles → arcs join across cell borders.
        if (hash21(i) > 0.5) f.x = 1.0 - f.x;
        // Two quarter-arcs per tile centered at opposite corners.
        float d = min(
            abs(distance(f, float2(0.0, 0.0)) - 0.5),
            abs(distance(f, float2(1.0, 1.0)) - 0.5)
        );
        float a = 1.0 - smoothstep(thickness, thickness + 0.02, d);
        half3 bg = half3(0.05, 0.10, 0.15);
        half3 fg = half3(0.95, 0.65, 0.20);
        return half4(mix(bg, fg, half(a)), 1.0);
    }

uniform float2 resolution;
uniform float density;
uniform float angle;
uniform float contrast;
half4 main(float2 fragCoord) {
    float2 uv = (fragCoord - 0.5 * resolution) / resolution.y;
    float theta = angle * 0.0174532925;
    float2 dirA = float2(1.0, 0.0);
    float2 dirB = float2(cos(theta), sin(theta));
    float stripeA = 0.5 + 0.5 * sin(dot(uv, dirA) * density);
    float stripeB = 0.5 + 0.5 * sin(dot(uv, dirB) * density);
    float beat = abs(stripeA - stripeB);
    float width = 0.25 / max(contrast, 0.1);
    float mask = smoothstep(0.5 - width, 0.5 + width, beat);
    float glow = smoothstep(0.72, 0.95, beat) * 0.35;
    half3 base = half3(0.05, 0.08, 0.16);
    half3 ink = half3(0.98, 0.78, 0.20);
    half3 accent = half3(0.18, 0.82, 0.95);
    half3 col = mix(base, ink, mask);
    col = mix(col, accent, glow);
    return half4(col, 1.0);
}

uniform float2 resolution;
uniform float segments;
uniform float twist;
uniform float scale;
half4 main(float2 fragCoord) {
    float2 uv = (fragCoord - 0.5 * resolution) / resolution.y;
    float radius = length(uv);
    float angle = atan(uv.y, uv.x) + radius * twist;
    float wedge = 6.28318530718 / max(segments, 2.0);
    float folded = abs(mod(angle + wedge * 0.5, wedge) - wedge * 0.5);
    float2 p = float2(cos(folded), sin(folded)) * radius * scale;
    float ribbons = 0.5 + 0.5 * sin((p.x + p.y) * 18.0);
    float cells = abs(fract(p.x * 3.0) - 0.5);
    float spokes = smoothstep(0.18, 0.48, cells);
    float petals = 0.5 + 0.5 * sin(12.0 * length(p) + 4.0 * sin(p.y * 3.0));
    float vignette = 1.0 - smoothstep(0.62, 0.95, radius);
    half3 bg = half3(0.06, 0.04, 0.14);
    half3 magenta = half3(0.90, 0.25, 0.65);
    half3 cyan = half3(0.25, 0.90, 0.95);
    half3 col = mix(bg, magenta, ribbons);
    col = mix(col, cyan, petals * spokes);
    return half4(col * vignette, 1.0);
}

uniform float2 resolution;
uniform float density;
uniform float threadWidth;
uniform float contrast;
half4 main(float2 fragCoord) {
    float2 uv = fragCoord / resolution;
    uv.x *= resolution.x / resolution.y;
    float2 cell = fract(uv * density);
    float vertical = 1.0 - smoothstep(threadWidth, threadWidth + 0.03, abs(cell.x - 0.5));
    float horizontal = 1.0 - smoothstep(threadWidth, threadWidth + 0.03, abs(cell.y - 0.5));
    float weave = clamp(vertical + horizontal * contrast, 0.0, 1.0);
    float overUnder = step(0.5, fract(floor(uv.x * density) + floor(uv.y * density) * 0.5));
    half3 base = half3(0.07, 0.09, 0.14);
    half3 warp = half3(0.85, 0.18, 0.34);
    half3 weft = half3(0.16, 0.72, 0.95);
    half3 thread = mix(warp, weft, half(overUnder));
    return half4(mix(base, thread, half(weave)), 1.0);
}

uniform float2 resolution;
uniform float scale;
uniform float width;
uniform float offset;
half4 main(float2 fragCoord) {
    float2 uv = (fragCoord - 0.5 * resolution) / resolution.y * scale;
    float2 tile = floor(uv);
    float2 cell = fract(uv) - 0.5;
    float parity = mod(tile.x + tile.y, 2.0);
    float2 p = parity < 1.0 ? float2(cell.x, cell.y) : float2(-cell.x, cell.y);
    p.x += (parity - 0.5) * offset;
    float stripe = abs(fract((p.x + p.y) * 3.0) - 0.5);
    float line = 1.0 - smoothstep(width, width + 0.035, stripe);
    float joint = max(
        smoothstep(0.46, 0.49, abs(cell.x)),
        smoothstep(0.46, 0.49, abs(cell.y))
    );
    half3 grout = half3(0.04, 0.05, 0.08);
    half3 woodA = half3(0.92, 0.58, 0.25);
    half3 woodB = half3(0.50, 0.22, 0.12);
    half3 wood = mix(woodB, woodA, half(line));
    return half4(mix(wood, grout, half(joint)), 1.0);
}

uniform float2 resolution;
uniform float rays;
uniform float twist;
uniform float softness;
half4 main(float2 fragCoord) {
    float2 uv = (fragCoord - 0.5 * resolution) / resolution.y;
    float radius = length(uv);
    float angle = atan(uv.y, uv.x) + radius * twist;
    float sector = fract(angle / 6.28318530718 * rays);
    float spoke = abs(sector - 0.5);
    float burst = smoothstep(softness, 0.5, spoke);
    float rings = 0.5 + 0.5 * sin(radius * 38.0);
    float fade = 1.0 - smoothstep(0.55, 0.92, radius);
    half3 bg = half3(0.06, 0.03, 0.11);
    half3 gold = half3(1.0, 0.72, 0.16);
    half3 violet = half3(0.38, 0.18, 0.82);
    half3 col = mix(violet, gold, half(burst));
    col = mix(bg, col, half(fade * (0.65 + rings * 0.35)));
    return half4(col, 1.0);
}

uniform float2 resolution;
uniform float scale;
uniform float mortar;
uniform float randomness;
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
half4 main(float2 fragCoord) {
    float2 uv = fragCoord / resolution;
    uv.x *= resolution.x / resolution.y;
    float2 brickUv = uv * float2(scale * 1.7, scale);
    float row = floor(brickUv.y);
    brickUv.x += (hash21(float2(row, 5.3)) - 0.5) * randomness * 0.6;
    float2 tile = floor(brickUv);
    float2 cell = fract(brickUv);
    float splitX = step(1.0 - randomness * 0.55, hash21(tile + float2(11.7, 11.7)));
    float splitY = (1.0 - splitX) * step(1.0 - randomness * 0.35, hash21(tile + float2(29.1, 29.1)));
    float2 divisions = float2(1.0 + splitX, 1.0 + splitY);
    float2 local = fract(cell * divisions);
    float2 subTile = floor(cell * divisions);
    float edgeX = min(local.x, 1.0 - local.x);
    float edgeY = min(local.y, 1.0 - local.y);
    float edge = min(edgeX, edgeY);
    float grout = 1.0 - smoothstep(mortar, mortar + 0.02, edge);
    float brickId = hash21(tile + subTile * 0.37);
    float shade = 0.15 * sin(brickId * 12.0 + row * 2.3);
    half3 mortarColor = half3(0.05, 0.055, 0.06);
    half3 brickA = half3(0.70, 0.18, 0.10);
    half3 brickB = half3(0.95, 0.42, 0.18);
    half3 brick = mix(brickA, brickB, half(0.5 + shade));
    return half4(mix(brick, mortarColor, half(grout)), 1.0);
}

uniform float2 resolution;
uniform float shift;
half4 main(float2 fragCoord) {
    float t = fragCoord.x / resolution.x;
    float3 a = float3(0.50, 0.50, 0.50);
    float3 b = float3(0.50, 0.50, 0.50);
    float3 c = float3(1.00, 1.00, 1.00);
    float3 d = float3(0.00, 0.33, 0.67);
    float3 col = a + b * cos(6.2831 * (c * t + d + shift));
    return half4(half3(col), 1.0);
}

uniform float2 resolution;
uniform float saturation;
// Standard hsv2rgb — k = mod(n + h*6, 6), c = v - v*s*max(min(k,4-k,1),0).
float3 hsv2rgb(float h, float s, float v) {
    float3 k = mod(float3(5.0, 3.0, 1.0) + h * 6.0, 6.0);
    return v - v * s * max(min(min(k, 4.0 - k), 1.0), 0.0);
}
half4 main(float2 fragCoord) {
    float2 uv = (fragCoord - 0.5 * resolution) / min(resolution.x, resolution.y);
    float r = length(uv) * 2.0;
    float a = atan(uv.y, uv.x) / 6.2831 + 0.5;
    float mask = 1.0 - smoothstep(0.95, 1.0, r);
    float3 col = hsv2rgb(a, saturation * clamp(r, 0.0, 1.0), 1.0) * mask;
    return half4(half3(col), 1.0);
}

uniform float2 resolution;
uniform float bias;
// Three-stop gradient: blend across two segments, biased by a power curve.
// Demonstrates how a non-linear remap of t reshapes a perceptually uniform ramp.
half4 main(float2 fragCoord) {
    float t = fragCoord.x / resolution.x;
    float p = pow(t, mix(0.4, 2.5, bias));
    float3 a = float3(0.10, 0.05, 0.30);
    float3 b = float3(0.95, 0.30, 0.55);
    float3 c = float3(1.00, 0.95, 0.65);
    float3 col = (p < 0.5)
        ? mix(a, b, p * 2.0)
        : mix(b, c, (p - 0.5) * 2.0);
    return half4(half3(col), 1.0);
}

uniform float2 resolution;
uniform float exposure;
// ACES filmic curve (Narkowicz 2015 approximation).
float3 aces(float3 x) {
    return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
}
half4 main(float2 fragCoord) {
    float2 uv = fragCoord / resolution;
    // Synthetic HDR signal — bright sun on cool sky.
    float sun = exp(-30.0 * length(uv - float2(0.7, 0.35)));
    float3 hdr = float3(0.20, 0.30, 0.55) + 8.0 * sun * float3(1.0, 0.85, 0.55);
    float3 mapped = aces(hdr * exposure);
    return half4(half3(mapped), 1.0);
}

    uniform float2 resolution;
    uniform float radius;

float sdCircle(float2 p, float r) {
    return length(p) - r;
}
float sdBox(float2 p, float2 b, float r) {
    float2 q = abs(p) - b;
    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}
float opSmoothUnion(float d1, float d2, float k) {
    float h = clamp(0.5 + 0.5 * (d2 - d1) / k, 0.0, 1.0);
    return mix(d2, d1, h) - k * h * (1.0 - h);
}

    half4 main(float2 fragCoord) {

float2 uv = fragCoord / resolution - 0.5;
uv.x *= resolution.x / resolution.y;

        float d = sdCircle(uv, radius);
        float a = 1.0 - smoothstep(0.0, 0.005, d);
        half3 col = mix(half3(0.05), half3(0.95, 0.45, 0.30), a);
        return half4(col, 1.0);
    }

    uniform float2 resolution;
    uniform float corner;

float sdCircle(float2 p, float r) {
    return length(p) - r;
}
float sdBox(float2 p, float2 b, float r) {
    float2 q = abs(p) - b;
    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}
float opSmoothUnion(float d1, float d2, float k) {
    float h = clamp(0.5 + 0.5 * (d2 - d1) / k, 0.0, 1.0);
    return mix(d2, d1, h) - k * h * (1.0 - h);
}

    half4 main(float2 fragCoord) {

float2 uv = fragCoord / resolution - 0.5;
uv.x *= resolution.x / resolution.y;

        float d = sdBox(uv, float2(0.30, 0.18), corner);
        float a = 1.0 - smoothstep(0.0, 0.005, d);
        half3 col = mix(half3(0.05), half3(0.30, 0.85, 0.95), a);
        return half4(col, 1.0);
    }

    uniform float2 resolution;
    uniform float time;
    uniform float smoothness;

float sdCircle(float2 p, float r) {
    return length(p) - r;
}
float sdBox(float2 p, float2 b, float r) {
    float2 q = abs(p) - b;
    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}
float opSmoothUnion(float d1, float d2, float k) {
    float h = clamp(0.5 + 0.5 * (d2 - d1) / k, 0.0, 1.0);
    return mix(d2, d1, h) - k * h * (1.0 - h);
}

    half4 main(float2 fragCoord) {

float2 uv = fragCoord / resolution - 0.5;
uv.x *= resolution.x / resolution.y;

        float d1 = sdCircle(uv - float2(sin(time)*0.25, cos(time)*0.25), 0.18);
        float d2 = sdCircle(uv - float2(cos(time*1.3)*0.20, sin(time*0.7)*0.20), 0.20);
        float d3 = sdCircle(uv - float2(sin(time*0.6)*0.30, sin(time*1.1)*0.10), 0.15);
        float d = opSmoothUnion(opSmoothUnion(d1, d2, smoothness), d3, smoothness);
        float a = 1.0 - smoothstep(0.0, 0.01, d);
        half3 col = mix(half3(0.05, 0.05, 0.10), half3(0.95, 0.30, 0.65), a);
        return half4(col, 1.0);
    }

uniform float2 resolution;
uniform float cells;
half4 main(float2 fragCoord) {
    float2 uv = fragCoord / resolution;
    float2 g = floor(uv * cells);
    float c = mod(g.x + g.y, 2.0);
    half3 col = mix(half3(0.10), half3(0.95, 0.85, 0.60), half(c));
    return half4(col, 1.0);
}

uniform float2 resolution;
uniform float time;
uniform float cells;
half4 main(float2 fragCoord) {
    float2 uv = fragCoord / resolution;
    float2 g = fract(uv * cells) - 0.5;
    float r = 0.18 + 0.10 * sin(time * 2.0);
    float d = length(g) - r;
    float a = 1.0 - smoothstep(0.0, 0.02, d);
    half3 col = mix(half3(0.04, 0.04, 0.08), half3(0.95, 0.45, 0.85), a);
    return half4(col, 1.0);
}

uniform float2 resolution;
uniform float density;
half4 main(float2 fragCoord) {
    float2 uv = fragCoord / resolution - 0.5;
    uv.x *= resolution.x / resolution.y;
    float r = length(uv);
    float bands = abs(fract(r * density) - 0.5);
    float a = smoothstep(0.45, 0.5, bands);
    half3 col = mix(half3(0.10, 0.05, 0.20), half3(0.30, 0.95, 0.85), a);
    return half4(col, 1.0);
}

    uniform float2 resolution;

float hash21(float2 p) {
    return fract(sin(dot(p, float2(12.9898, 78.233))) * 43758.5453);
}
float valueNoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    float a = hash21(i);
    float b = hash21(i + float2(1.0, 0.0));
    float c = hash21(i + float2(0.0, 1.0));
    float d = hash21(i + float2(1.0, 1.0));
    float2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}
float fbm(float2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 6; i++) {
        v += a * valueNoise(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

    half4 main(float2 fragCoord) {
        float2 uv = fragCoord / resolution;
        float v = hash21(floor(uv * 64.0));
        return half4(half3(v), 1.0);
    }

    uniform float2 resolution;

float hash21(float2 p) {
    return fract(sin(dot(p, float2(12.9898, 78.233))) * 43758.5453);
}
float valueNoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    float a = hash21(i);
    float b = hash21(i + float2(1.0, 0.0));
    float c = hash21(i + float2(0.0, 1.0));
    float d = hash21(i + float2(1.0, 1.0));
    float2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}
float fbm(float2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 6; i++) {
        v += a * valueNoise(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

    half4 main(float2 fragCoord) {
        float2 uv = fragCoord / resolution;
        float v = valueNoise(uv * 8.0);
        return half4(half3(v), 1.0);
    }

    uniform float2 resolution;
    uniform float octaves;

float hash21(float2 p) {
    return fract(sin(dot(p, float2(12.9898, 78.233))) * 43758.5453);
}
float valueNoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    float a = hash21(i);
    float b = hash21(i + float2(1.0, 0.0));
    float c = hash21(i + float2(0.0, 1.0));
    float d = hash21(i + float2(1.0, 1.0));
    float2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}
float fbm(float2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 6; i++) {
        v += a * valueNoise(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

    half4 main(float2 fragCoord) {
        float2 uv = fragCoord / resolution;
        float2 p = uv * 4.0;
        float v = 0.0;
        float amp = 0.5;
        for (int i = 0; i < 6; i++) {
            if (float(i) >= octaves) break;
            v += amp * valueNoise(p);
            p *= 2.0;
            amp *= 0.5;
        }
        half3 sky = mix(half3(0.10, 0.20, 0.40), half3(0.95, 0.95, 1.00), half(v));
        return half4(sky, 1.0);
    }

